insert into natural_english_private.catalogue(module,senses,questions) values
('advanced-native-653', '["phrase"]'::jsonb, '{"advanced-native-653-v1-audio":{"type":"mc","answers":["The speaker assumed identical opening times, then used local notices to check each visit."],"options":["The speaker used another city’s timetable for the next visit without checking that venue.","The speaker assumed identical opening times, then used local notices to check each visit.","The speaker had compared every venue before forming the original timetable.","The two venues displayed the same opening hours, confirming the original plan."]},"advanced-native-653-v2-reply":{"type":"mc","answers":["I had painted all overseas cities with the same brush, but the different notices showed that my opening-time assumption did not hold.","The venues did not share the identical hours I had expected.","Local information gave me a reason to check rather than reuse the old timetable.","The difference concerned practical visiting arrangements, not a judgement that one place was better."],"options":["I had painted all overseas cities with the same brush, but the different notices showed that my opening-time assumption did not hold.","The venues did not share the identical hours I had expected.","Local information gave me a reason to check rather than reuse the old timetable.","The difference concerned practical visiting arrangements, not a judgement that one place was better."]},"advanced-native-653-v1-scene":{"type":"mc","answers":["We should not paint all cities with the same brush; the riverside setting does not settle their booking arrangements."],"options":["We should not paint all cities with the same brush; the riverside setting does not settle their booking arrangements.","The similar location confirms that neither exhibition requires any booking.","The account says both organisers have agreed to use one shared entry rule."]},"advanced-native-653-v1-contrast":{"type":"mc","answers":["Their opening and entry arrangements are identical in every relevant respect."],"options":["Their opening and entry arrangements are identical in every relevant respect.","Local information may be needed to plan a visit.","A similarity should be separated from unexamined differences."]},"advanced-native-653-v1-branch":{"type":"mc","answers":["Let us not paint all cities with the same brush; check this exhibition’s entry notice rather than infer it from the riverside location."],"options":["Let us not paint all cities with the same brush; check this exhibition’s entry notice rather than infer it from the riverside location.","Yes, the shared location means both exhibitions use the same booking system.","The two organisers have already given us one joint confirmation, so no separate rule applies."]},"advanced-native-653-v1-final":{"type":"open","answers":["The breakfast scene is worth keeping, but let us not paint all overseas cities with the same brush from this one visit. Could you name the city and your own morning, then leave the next place as something still to discover?","You can keep the riverside breakfast without painting all cities with the same brush. I would frame it as the morning you experienced, not a rule about places the character has not yet visited."],"options":[]}}'::jsonb),
('advanced-native-657', '["phrase"]'::jsonb, '{"advanced-native-657-v1-audio":{"type":"mc","answers":["The gate’s evening access affected the route, so the caretaker was asked before visitors were advised."],"options":["The gate had been removed before anyone considered the route.","The gate’s evening access affected the route, so the caretaker was asked before visitors were advised.","The shortest drawn line had already been confirmed open at every time.","The group discarded the map and decided no location information was useful."]},"advanced-native-657-v2-reply":{"type":"mc","answers":["Planning meant more than drawing lines on a map because the evening gate could interrupt the actual walk.","The drawn connection did not establish whether visitors could pass through at the needed time.","The caretaker’s information was needed to understand how the route worked in practice.","A short distance on paper was not enough to confirm usable access."],"options":["Planning meant more than drawing lines on a map because the evening gate could interrupt the actual walk.","The drawn connection did not establish whether visitors could pass through at the needed time.","The caretaker’s information was needed to understand how the route worked in practice.","A short distance on paper was not enough to confirm usable access."]},"advanced-native-657-v1-scene":{"type":"mc","answers":["Drawing lines on a map can show the route, but we still need residents’ accounts before describing their relationships."],"options":["The opened path records residents explaining the friendships it has already created.","The map contains the households’ social contacts rather than the position of the path.","Drawing lines on a map can show the route, but we still need residents’ accounts before describing their relationships."]},"advanced-native-657-v1-contrast":{"type":"mc","answers":["Assume a marked connection proves access at every needed time."],"options":["Use the drawing and investigate what happens along the route.","Assume a marked connection proves access at every needed time.","Distinguish represented space from how people can use it."]},"advanced-native-657-v1-branch":{"type":"mc","answers":["The route needs more than drawing lines on a map; let us ask when the gate is usable before recommending it."],"options":["We should recommend a longer route solely because it looks less direct on paper.","The route needs more than drawing lines on a map; let us ask when the gate is usable before recommending it.","Yes, the drawn line overrides the gate’s actual opening conditions."]},"advanced-native-657-v1-final":{"type":"open","answers":["Drawing lines on a map tells us where this path is proposed, but not what it would mean in your day. Tell us about a journey, a place to pause or a caring responsibility that you would want the plan to consider.","We want to go beyond drawing lines on a map by hearing how people might use the space. Your experience may add a need or a question we have missed; you do not have to agree with the proposal to contribute."],"options":[]}}'::jsonb),
('advanced-native-658', '["phrase"]'::jsonb, '{"advanced-native-658-v1-audio":{"type":"mc","answers":["Repeated entrances and a limited view confused the newcomer, while a resident could identify a route."],"options":["Repeated entrances and a limited view confused the newcomer, while a resident could identify a route.","The confusion came from contradictory directions given by the resident, rather than the entrances and view.","The resident had no idea where any marked route led.","The visitor was describing a route used every day rather than an unfamiliar first visit."]},"advanced-native-658-v2-reply":{"type":"mc","answers":["My view lacked the landmarks that the resident already knew how to use.","It felt like a concrete maze because the similar entrances and hidden street made orientation difficult.","I could not distinguish the courtyard approaches easily from where I stood.","The repeated built forms made it hard for me to relate the entrances to the street."],"options":["My view lacked the landmarks that the resident already knew how to use.","It felt like a concrete maze because the similar entrances and hidden street made orientation difficult.","I could not distinguish the courtyard approaches easily from where I stood.","The repeated built forms made it hard for me to relate the entrances to the street."]},"advanced-native-658-v1-scene":{"type":"mc","answers":["Concrete alone does not make it a concrete maze when the described routes are clear to the visitors."],"options":["The visitors’ successful route confirms that no directions were present.","Concrete alone does not make it a concrete maze when the described routes are clear to the visitors.","The account says the signs were identical and the visitors could not find any entrance."]},"advanced-native-658-v1-contrast":{"type":"mc","answers":["Residents deliberately designed a trap for the visitor."],"options":["The layout is experienced as confusing to navigate.","Residents deliberately designed a trap for the visitor.","A different viewpoint or local knowledge may change the experience."]},"advanced-native-658-v1-branch":{"type":"mc","answers":["No, I meant that the layout felt like a concrete maze to me; your directions helped me understand it."],"options":["Yes, my first confusion is enough to know that you intended to trap me.","I never had trouble with the entrances, so there was no reason to ask for directions.","No, I meant that the layout felt like a concrete maze to me; your directions helped me understand it."]},"advanced-native-658-v1-final":{"type":"open","answers":["I am sorry I turned my experience of a concrete maze into a claim about everyone’s intentions. I meant that I could not read the layout at first, and I should have included how your help made the route clearer.","Calling the estate a concrete maze described my confusion, but saying people wanted to keep outsiders away went beyond what I knew. Thank you for showing me the route; I will correct that unfair assumption."],"options":[]}}'::jsonb),
('advanced-native-659', '["phrase"]'::jsonb, '{"advanced-native-659-v1-audio":{"type":"mc","answers":["The opening reduced residents to accommodation details, so the reviewer wanted their choices shown."],"options":["The reviewer said residents themselves had no feelings or ability to act.","The opening already followed named residents making choices throughout the chapter.","The request was for a larger table of room sizes instead of any character scene.","The opening reduced residents to accommodation details, so the reviewer wanted their choices shown."]},"advanced-native-659-v2-reply":{"type":"mc","answers":["Accommodation details dominated the opening while human experiences were absent.","The reviewer had no character decisions to follow in the listed rooms.","It resembled a machine for storing people because room numbers replaced residents’ names and actions.","The description told us where people were placed without showing what they chose to do."],"options":["Accommodation details dominated the opening while human experiences were absent.","The reviewer had no character decisions to follow in the listed rooms.","It resembled a machine for storing people because room numbers replaced residents’ names and actions.","The description told us where people were placed without showing what they chose to do."]},"advanced-native-659-v1-scene":{"type":"mc","answers":["The first image may suggest a machine for storing people, but the later actions give the residents choices and voices."],"options":["The first image may suggest a machine for storing people, but the later actions give the residents choices and voices.","The later actions are only promises about future scenes, rather than events actually shown.","The account says the later pages contain only larger room-number diagrams."]},"advanced-native-659-v1-contrast":{"type":"mc","answers":["Declare that the people themselves are worthless objects."],"options":["Declare that the people themselves are worthless objects.","Explain what experience or choice would add the missing human dimension.","Question whether planning or description leaves out residents’ active lives."]},"advanced-native-659-v1-branch":{"type":"mc","answers":["No, a machine for storing people describes the opening’s narrow view; I want the residents’ feelings and choices to become visible."],"options":["I am asking for the housing to disappear, rather than for the story to show its people.","No, a machine for storing people describes the opening’s narrow view; I want the residents’ feelings and choices to become visible.","Yes, the room numbers prove the residents have no inner lives."]},"advanced-native-659-v1-final":{"type":"open","answers":["I need a home, but I do not want this city to become a machine for storing people. Ask me when I want company, when I need quiet and where I can care for a few plants, rather than only how many rooms will hold me.","A machine for storing people would leave no place for the choices that make this a home for me. I want somewhere to live and some say in the ordinary things I do there, without claiming to speak for every neighbour."],"options":[]}}'::jsonb),
('advanced-native-660', '["phrase"]'::jsonb, '{"advanced-native-660-v1-audio":{"type":"mc","answers":["A practised action suggested a background connection without yet identifying its source."],"options":["The reader had already watched the training scene before the fold appeared.","A practised action suggested a background connection without yet identifying its source.","The action confirms that she currently works at the place where this scene is set.","The fold is a new skill she is trying for the first time in this scene."]},"advanced-native-660-v2-reply":{"type":"mc","answers":["It gave away clues about an earlier part of her life without explaining the whole history at once.","The repeated precision suggested an experience the reader had not yet seen.","The action could make readers ask where she had learned it.","A small physical habit hinted at a past connection before the later scene supplied context."],"options":["It gave away clues about an earlier part of her life without explaining the whole history at once.","The repeated precision suggested an experience the reader had not yet seen.","The action could make readers ask where she had learned it.","A small physical habit hinted at a past connection before the later scene supplied context."]},"advanced-native-660-v1-scene":{"type":"mc","answers":["The number may give away clues, but it does not by itself establish her occupation."],"options":["The station number confirms that she currently works there rather than visiting for another reason.","The current scene states her occupation directly rather than leaving the number unexplained.","The number may give away clues, but it does not by itself establish her occupation."]},"advanced-native-660-v1-contrast":{"type":"mc","answers":["The hint supplies a complete, unique explanation without further context."],"options":["Some detail reveals a hint.","The hint supplies a complete, unique explanation without further context.","The revealing can be unintended, while an author may also place it deliberately."]},"advanced-native-660-v1-branch":{"type":"mc","answers":["It gives away clues, but let us keep that as a possibility until the story supplies more context."],"options":["Yes, the single fold confirms the employer without any other scene.","She has already explained her entire career to us, so the clue adds no uncertainty.","It gives away clues, but let us keep that as a possibility until the story supplies more context."]},"advanced-native-660-v1-final":{"type":"open","answers":["The envelope in the corner could give away clues about where you live, even though the photograph is meant to show the gathering. Would you like to keep that detail, crop it out or cover the writing before we share the booklet?","Small background details can give away clues that you did not mean to share. Could we look at the envelope together and decide what you are comfortable including, rather than assume your agreement to the gathering photograph covers everything in it?"],"options":[]}}'::jsonb),
('advanced-native-662', '["phrase"]'::jsonb, '{"advanced-native-662-v1-audio":{"type":"mc","answers":["The broad beginning and ending were described, while middle scenes and decisions remained open."],"options":["Every scene and line of dialogue had already been fixed in the final script.","The group had no information about either the starting problem or the ending.","The writer had drawn detailed pictures instead of describing any story direction.","The broad beginning and ending were described, while middle scenes and decisions remained open."]},"advanced-native-662-v2-reply":{"type":"mc","answers":["The account gave enough shape for discussion, not a complete script.","Some character choices still needed to be developed within the proposed direction.","The writer sketched the outline, giving a broad route but leaving the middle scenes unwritten.","We knew the starting problem and final meeting without having every link between them."],"options":["The account gave enough shape for discussion, not a complete script.","Some character choices still needed to be developed within the proposed direction.","The writer sketched the outline, giving a broad route but leaving the middle scenes unwritten.","We knew the starting problem and final meeting without having every link between them."]},"advanced-native-662-v1-scene":{"type":"mc","answers":["It does more than sketch the outline, because the described document supplies detailed instructions and responsibilities."],"options":["The account says the steps and responsible people are still entirely unspecified.","The dates appear only as questions for a future draft, not in the current instructions.","It does more than sketch the outline, because the described document supplies detailed instructions and responsibilities."]},"advanced-native-662-v1-contrast":{"type":"mc","answers":["Every private detail has been shared and approved for publication."],"options":["Every private detail has been shared and approved for publication.","Leave some details for later or for the speaker’s choice.","Provide the broad shape of an account."]},"advanced-native-662-v1-branch":{"type":"mc","answers":["We have sketched the outline, not the full script; the middle scenes still need developing."],"options":["Yes, a broad direction counts as every line already being written.","There is no starting point or ending to discuss because the middle is unfinished.","We have sketched the outline, not the full script; the middle scenes still need developing."]},"advanced-native-662-v1-final":{"type":"open","answers":["You can sketch the outline of the move without going into the family disagreements you prefer to keep private. Afterwards, we can agree which parts you would like recorded or shared, rather than assume your whole account is for publication.","Let us sketch the outline first, at the level of detail you choose. We can leave the private parts untouched and decide together what, if anything, belongs in the written account."],"options":[]}}'::jsonb),
('advanced-native-664', '["phrase"]'::jsonb, '{"advanced-native-664-v1-audio":{"type":"mc","answers":["It made the role recognisable while rehearsal of the scene remained necessary."],"options":["The apron established that Ravi worked professionally as a gardener outside the play.","It made the role recognisable while rehearsal of the scene remained necessary.","The director had asked him only to choose clothes, with no scene practice expected.","The notes required a different character, so Ravi was ignoring the stated role."]},"advanced-native-664-v2-reply":{"type":"mc","answers":["He wanted to dress the part of the gardener described in the play.","The director’s notes used that clothing to make the role recognisable.","It supported the character’s appearance without doing the acting for him.","The costume matched the specific role he was preparing to perform."],"options":["He wanted to dress the part of the gardener described in the play.","The director’s notes used that clothing to make the role recognisable.","It supported the character’s appearance without doing the acting for him.","The costume matched the specific role he was preparing to perform."]},"advanced-native-664-v1-scene":{"type":"mc","answers":["You can dress the part by following the stated expectation; the phrase does not itself require the most expensive suit."],"options":["The account says comfort is forbidden and no dress expectation has been given.","You can dress the part by following the stated expectation; the phrase does not itself require the most expensive suit.","The invitation explicitly requires the highest-priced formal suit."]},"advanced-native-664-v1-contrast":{"type":"mc","answers":["The wearer has already proved every skill the role requires."],"options":["Relevant expectations can differ between settings.","Clothing fits the expected role or occasion.","The wearer has already proved every skill the role requires."]},"advanced-native-664-v1-branch":{"type":"mc","answers":["I can dress the part, but I still need to rehearse the words and actions."],"options":["I can spend the rehearsal adjusting the costume instead of practising the unfamiliar lines.","I am preparing a gardening demonstration, so I should explain the tools rather than follow the scripted dialogue.","I can dress the part, but I still need to rehearse the words and actions."]},"advanced-native-664-v1-final":{"type":"open","answers":["I would like to dress the part for the celebration without buying a jacket for one evening. Would my neat older jacket fit the level of formality you have in mind, or is there a specific expectation I should know about?","I want to dress the part, and I already have a tidy jacket I would prefer to use. Could you tell me what the invitation’s dress note means for this particular gathering before I decide?"],"options":[]}}'::jsonb),
('advanced-native-665', '["phrase"]'::jsonb, '{"advanced-native-665-v1-audio":{"type":"mc","answers":["A request for rough discussion notes was read as a finished-article deadline, then checked with the editor."],"options":["The writer understood the requested level from the start and needed no clarification.","The editor’s intent was established by a rumour rather than by asking her.","A request for rough discussion notes was read as a finished-article deadline, then checked with the editor.","The editor explicitly demanded a published article and rejected all rough notes."]},"advanced-native-665-v2-reply":{"type":"mc","answers":["I had assumed a finished article was required, but the editor meant rough notes.","Clarifying the preparation level could prevent work based on the wrong expectation.","The uncertainty concerned what to bring, not a confirmed decision to reject the article.","I had got the wrong end of the stick about what counted as a draft and wanted to confirm it."],"options":["I had assumed a finished article was required, but the editor meant rough notes.","Clarifying the preparation level could prevent work based on the wrong expectation.","The uncertainty concerned what to bring, not a confirmed decision to reject the article.","I had got the wrong end of the stick about what counted as a draft and wanted to confirm it."]},"advanced-native-665-v1-scene":{"type":"mc","answers":["She checked the meaning instead of getting the wrong end of the stick and treating a temporary pause as a permanent ban."],"options":["She checked the meaning instead of getting the wrong end of the stick and treating a temporary pause as a permanent ban.","She concluded that the work could never be revised and did not ask anyone.","The reply confirmed a permanent ban rather than waiting for feedback."]},"advanced-native-665-v1-contrast":{"type":"mc","answers":["The other person deliberately lied to cause the mistake."],"options":["The other person deliberately lied to cause the mistake.","A clear explanation can identify what was misread.","Someone has misunderstood a point."]},"advanced-native-665-v1-branch":{"type":"mc","answers":["I think you have got the wrong end of the stick: she asked for rough notes to discuss, not a finished article."],"options":["The editor has already rejected the article, although we have not discussed it yet.","I think you have got the wrong end of the stick: she asked for rough notes to discuss, not a finished article.","Yes, rough notes and a finished article are the same level of preparation."]},"advanced-native-665-v1-final":{"type":"open","answers":["I got the wrong end of the stick and read your wish for privacy as a rejection of our conversation. I am sorry for the cold reply; would you like to share the poem privately, and what kind of feedback would feel useful now?","I think I got the wrong end of the stick about what you meant by not sharing publicly. I would like to listen on the terms you choose, without expecting you to agree to publication because I misunderstood."],"options":[]}}'::jsonb),
('advanced-native-666', '["phrase"]'::jsonb, '{"advanced-native-666-v1-audio":{"type":"mc","answers":["A stained shirt prompted doubt, while the useful checklist showed an actual contribution."],"options":["The checklist was never used because the shirt proved the member could not organise anything.","The coordinator decided he could help only with painting, rather than planning.","The group examined the checklist first and questioned its contents, rather than reacting to his shirt.","A stained shirt prompted doubt, while the useful checklist showed an actual contribution."]},"advanced-native-666-v2-reply":{"type":"mc","answers":["The outward stain did not establish that he lacked organisational care.","The useful work challenged an assumption made before examining his contribution.","They were judging a book by its cover when they doubted him from the paint-stained shirt.","His checklist gave more relevant evidence of how he helped the display."],"options":["The outward stain did not establish that he lacked organisational care.","The useful work challenged an assumption made before examining his contribution.","They were judging a book by its cover when they doubted him from the paint-stained shirt.","His checklist gave more relevant evidence of how he helped the display."]},"advanced-native-666-v1-scene":{"type":"mc","answers":["Calling the game poor from the plain box would judge a book by its cover rather than use the play experience."],"options":["The account says the group has not yet tried the game or discussed the rules.","Calling the game poor from the plain box would judge a book by its cover rather than use the play experience.","The plain box suggests poorly explained rules, so the group should discount their successful trial."]},"advanced-native-666-v1-contrast":{"type":"mc","answers":["Assume attractive presentation proves the content is already excellent."],"options":["Look for qualities relevant to the actual task.","Assume attractive presentation proves the content is already excellent.","Distinguish a first impression from a supported judgement."]},"advanced-native-666-v1-branch":{"type":"mc","answers":["Let us not judge a book by its cover; the checklist is relevant evidence of what he has contributed."],"options":["Yes, a shirt stain settles whether his planning can be useful.","The useful checklist is enough to decide his suitability for the reception task, without checking that task’s practical requirements.","Let us not judge a book by its cover; the checklist is relevant evidence of what he has contributed."]},"advanced-native-666-v1-final":{"type":"open","answers":["Please do not judge a book by its cover from the plain hall alone; the programme will tell you more about the play. Would you like to read it and decide whether the story interests you, rather than feel obliged to come just because I invited you?","I would rather not judge a book by its cover when choosing this performance. I can send you the synopsis so you can decide for yourself, without promising that a simple venue makes the play right for everyone."],"options":[]}}'::jsonb),
('advanced-native-667', '["phrase"]'::jsonb, '{"advanced-native-667-v1-audio":{"type":"mc","answers":["The cousins knew a family connection that the visitor did not share."],"options":["The cousins knew a family connection that the visitor did not share.","Every observer had already heard the same complete history of the coat.","The visitor had made the coat and explained its meaning to the cousins.","The cousins saw a new garment with no link to anyone they knew."]},"advanced-native-667-v2-reply":{"type":"mc","answers":["The different responses showed that appearance did not carry one complete explanation for everyone.","Clothes may speak through associations, but the cousins’ memories were not shared by the visitor.","The same visible coat connected to a person the cousins remembered.","Seeing an old garment did not give the visitor the family story behind it."],"options":["The different responses showed that appearance did not carry one complete explanation for everyone.","Clothes may speak through associations, but the cousins’ memories were not shared by the visitor.","The same visible coat connected to a person the cousins remembered.","Seeing an old garment did not give the visitor the family story behind it."]},"advanced-native-667-v1-scene":{"type":"mc","answers":["Clothes may speak to the observer, but we should ask what the wearer intended before treating that reading as fact."],"options":["The wearer has already given a full explanation, so no interpretation is being assumed.","Clothes may speak to the observer, but we should ask what the wearer intended before treating that reading as fact.","The observer’s first association confirms the wearer’s exact intention."]},"advanced-native-667-v1-contrast":{"type":"mc","answers":["The observer necessarily knows the wearer’s complete personality and intention."],"options":["Different backgrounds can lead to different readings.","Clothing can suggest an impression before words are exchanged.","The observer necessarily knows the wearer’s complete personality and intention."]},"advanced-native-667-v1-branch":{"type":"mc","answers":["Clothes may speak, but your association is not yet her explanation; why not ask what she likes about it?"],"options":["Clothes may speak, but your association is not yet her explanation; why not ask what she likes about it?","Yes, your first reading settles her reason for choosing it.","She has already told us that it has the meaning you guessed, although we have not asked her."]},"advanced-native-667-v1-final":{"type":"open","answers":["Clothes may speak, and my suit seems to have suggested that I am hosting, but I am here as a guest. I dressed for the occasion to celebrate my friend, and I am very happy to join you in congratulating her.","If clothes may speak, mine have apparently given me a role I do not have tonight. I am simply a guest who wanted to honour a friend’s achievement, so let me add my congratulations rather than take over the programme."],"options":[]}}'::jsonb),
('advanced-native-668', '["phrase"]'::jsonb, '{"advanced-native-668-v1-audio":{"type":"mc","answers":["She expressed happiness and gratitude privately while declining a public announcement for that week."],"options":["Her note announced that she was leaving illustration rather than continuing her work.","She expressed happiness and gratitude privately while declining a public announcement for that week.","She was disappointed with the prize and refused to thank the group.","She asked the group to arrange a large public announcement immediately."]},"advanced-native-668-v2-reply":{"type":"mc","answers":["She wanted a low-key response while still thanking the people who helped.","She preferred to share her delight privately rather than announce the prize publicly that week.","A short note suited the quiet manner she wanted for acknowledging the support.","She could express real gratitude without making the news a public event."],"options":["She wanted a low-key response while still thanking the people who helped.","She preferred to share her delight privately rather than announce the prize publicly that week.","A short note suited the quiet manner she wanted for acknowledging the support.","She could express real gratitude without making the news a public event."]},"advanced-native-668-v1-scene":{"type":"mc","answers":["Her manner can be low-key even though the paintings themselves are bold."],"options":["Her manner can be low-key even though the paintings themselves are bold.","The description says her paintings use only faint colours and delicate lines.","The strong colours show that she prefers an elaborate public response in every interview."]},"advanced-native-668-v1-contrast":{"type":"mc","answers":["The person is necessarily unhappy with the achievement."],"options":["The presentation avoids attracting a great deal of public attention.","The person is necessarily unhappy with the achievement.","A sincere response can be quiet rather than elaborate."]},"advanced-native-668-v1-branch":{"type":"mc","answers":["She said she was delighted; a low-key thank-you is simply how she wants to share it this week."],"options":["She said she was delighted; a low-key thank-you is simply how she wants to share it this week.","I think she is disappointed with the result, despite what she said about being delighted.","Let us publish the announcement now; her private thanks should count as agreement to that."]},"advanced-native-668-v1-final":{"type":"open","answers":["I would like to keep my support low-key and respect your wish not to discuss the result in the group. If you would welcome some company over tea, I am here, but there is no need to reply now.","We can keep this low-key: I will not start a group discussion or arrange a surprise gathering. Let me know if a quiet cup of tea would help, whenever you feel ready to answer."],"options":[]}}'::jsonb),
('advanced-native-669', '["phrase"]'::jsonb, '{"advanced-native-669-v1-audio":{"type":"mc","answers":["It showed turnout, while understanding and access to help still needed checking."],"options":["The review excluded attendance and considered only the colour of the posters.","Visitor interviews had already answered every question before the review began.","It showed turnout, while understanding and access to help still needed checking.","The number alone established that every visitor understood the activities."]},"advanced-native-669-v2-reply":{"type":"mc","answers":["Many people arriving did not tell us how clearly they understood the activities.","We still needed visitors’ experiences of following the sessions and finding answers.","Turnout mattered, but the review also concerned what people could actually do once they arrived.","Attendance was one piece of the puzzle, not a full account of whether visitors could take part and get help."],"options":["Many people arriving did not tell us how clearly they understood the activities.","We still needed visitors’ experiences of following the sessions and finding answers.","Turnout mattered, but the review also concerned what people could actually do once they arrived.","Attendance was one piece of the puzzle, not a full account of whether visitors could take part and get help."]},"advanced-native-669-v1-scene":{"type":"mc","answers":["The photograph is one piece of the puzzle, but it does not by itself establish the date of her move."],"options":["The photograph records the exact moving date, so the remaining documents are irrelevant.","Because the photograph is incomplete evidence, it tells us nothing about where she was that year.","The photograph is one piece of the puzzle, but it does not by itself establish the date of her move."]},"advanced-native-669-v1-contrast":{"type":"mc","answers":["That factor alone necessarily settles the whole explanation."],"options":["Other evidence may change how the factor is understood.","A factor contributes to a fuller account.","That factor alone necessarily settles the whole explanation."]},"advanced-native-669-v1-branch":{"type":"mc","answers":["The turnout is one piece of the puzzle; let us ask how easily visitors found help before making that claim."],"options":["Yes, a large turnout is enough evidence that the help arrangements worked for everyone.","We should leave turnout out of the review altogether, since it cannot answer every question.","The turnout is one piece of the puzzle; let us ask how easily visitors found help before making that claim."]},"advanced-native-669-v1-final":{"type":"open","answers":["The missed call is only one piece of the puzzle, and I do not know what was happening for you last night. Could you tell me when it would be a good time to talk, rather than let me guess what your silence meant?","I treated one unanswered call as if it explained how you felt about me, but it is only a piece of the puzzle. I would rather ask about your evening and find a time that suits us both."],"options":[]}}'::jsonb),
