('advanced-native-674', '["phrase"]'::jsonb, '{"advanced-native-674-v1-audio":{"type":"mc","answers":["The early enthusiasm weakened over weeks, while one member still expressed interest in trying again."],"options":["The messages grew more frequent, showing steadily rising enthusiasm.","A new session had already solved the participation difficulties before she asked about them.","The early enthusiasm weakened over weeks, while one member still expressed interest in trying again.","All members suddenly stopped caring at exactly the same moment."]},"advanced-native-674-v2-reply":{"type":"mc","answers":["The regular signs of enthusiasm diminished over time rather than growing stronger.","The change involved a falling level of activity across weeks, not one quiet minute.","Comparing the weeks showed less frequent engagement than at the beginning.","It faded away as the group’s messages became less frequent over several weeks."],"options":["The regular signs of enthusiasm diminished over time rather than growing stronger.","The change involved a falling level of activity across weeks, not one quiet minute.","Comparing the weeks showed less frequent engagement than at the beginning.","It faded away as the group’s messages became less frequent over several weeks."]},"advanced-native-674-v1-scene":{"type":"mc","answers":["The song has not faded away, although its everyday role has changed."],"options":["The account describes the song being forgotten completely, with no remaining performance.","The song has not faded away, although its everyday role has changed.","The annual singing establishes that every family still sings it daily."]},"advanced-native-674-v1-contrast":{"type":"mc","answers":["It must disappear suddenly without any weakening process."],"options":["Interest can lose intensity even if some concern remains.","A sound can become quieter over time.","It must disappear suddenly without any weakening process."]},"advanced-native-674-v1-branch":{"type":"mc","answe